// Verify the shared secret first. Knowing this URL must not be enough to
// make the church's server render video.
const crypto = require('crypto');

const secret = $env.PIPELINE_SECRET;
if (!secret) throw new Error('PIPELINE_SECRET is not set on this n8n instance.');

const item = $input.first();
const b64 = item.binary?.data?.data;
if (!b64) throw new Error('The webhook is not configured to pass the raw body.');

const raw = Buffer.from(b64, 'base64').toString('utf8');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
const got = item.json.headers['x-signature'] || '';

const a = Buffer.from(expected);
const b = Buffer.from(got);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Signature mismatch. Check that the app and n8n share the same PIPELINE_SECRET.');
}

const body = JSON.parse(raw);
const p = body.payload || {};

return [{
  json: {
    jobId: body.jobId,
    callbackUrl: body.callbackUrl,
    announcementId: p.announcementId,
    title: p.title,
    sectionCount: (p.sections || []).length,
    outputKey: p.output?.key,
    putUrl: p.output?.putUrl,
    outPath: `/data/out/${body.jobId}.mp4`,
    // plan carries intro, outro and sections through to the render step.
    // Dropping any of them here is how bookends go missing from the output.
    plan: p
  }
}];

// Write the render plan to disk, and sign a "working on it" callback. The
// plan goes to a file rather than the command line so a poster filename with
// a quote in it cannot break the shell.
const crypto = require('crypto');
const fs = require('fs');

const ctx = $('Check signature').first().json;

fs.mkdirSync('/data/jobs', { recursive: true });
const planPath = `/data/jobs/${ctx.jobId}.json`;
fs.writeFileSync(planPath, JSON.stringify({
  jobId: ctx.jobId,
  outPath: ctx.outPath,
  intro: ctx.plan.intro,
  outro: ctx.plan.outro,
  // One recording covering every section, when the person uploaded one.
  // The assembler switches on its presence, so dropping it here would
  // silently fall back to per-section audio that is not there.
  narration: ctx.plan.narration,
  sections: ctx.plan.sections
}));

const body = JSON.stringify({
  status: 'rendering',
  progress: 10,
  stepLabel: `Rendering ${ctx.sectionCount} ${ctx.sectionCount === 1 ? 'section' : 'sections'}`
});

const signature = 'sha256=' + crypto
  .createHmac('sha256', $env.PIPELINE_SECRET)
  .update(body, 'utf8')
  .digest('hex');

return [{ json: { planPath, callbackUrl: ctx.callbackUrl, body, signature } }];

const crypto = require('crypto');

const ctx = $('Check signature').first().json;

// The script prints only its result JSON on stdout; FFmpeg chatter went to a
// log file, so this parse is safe.
let durationMs = 0;
try {
  durationMs = JSON.parse($('Run FFmpeg').first().json.stdout).durationMs || 0;
} catch (cause) {
  durationMs = 0;
}

const body = JSON.stringify({
  status: 'complete',
  progress: 100,
  stepLabel: 'Video ready',
  artifact: {
    key: ctx.outputKey,
    filename: `${(ctx.title || 'announcement').replace(/[^a-z0-9]+/gi, '-').toLowerCase()}.mp4`,
    contentType: 'video/mp4',
    durationMs
  }
});

const signature = 'sha256=' + crypto
  .createHmac('sha256', $env.PIPELINE_SECRET)
  .update(body, 'utf8')
  .digest('hex');

return [{ json: { callbackUrl: ctx.callbackUrl, body, signature } }];

// The render stopped. Send back something the person can act on rather than
// a stack trace: the last few lines of FFmpeg's own log.
const crypto = require('crypto');
const fs = require('fs');

const ctx = $('Check signature').first().json;
const failure = $input.first().json;

let tail = '';
try {
  const log = fs.readFileSync(`/data/work/${ctx.jobId}/ffmpeg.log`, 'utf8');
  tail = log.trim().split('\n').slice(-4).join(' ');
} catch (cause) {
  tail = '';
}

const reason = tail || failure.stderr || failure.error?.message || 'no detail was reported';

const body = JSON.stringify({
  status: 'failed',
  stepLabel: 'Render stopped',
  error: `The render stopped. ${reason}`.slice(0, 1900)
});

const signature = 'sha256=' + crypto
  .createHmac('sha256', $env.PIPELINE_SECRET)
  .update(body, 'utf8')
  .digest('hex');

return [{ json: { callbackUrl: ctx.callbackUrl, body, signature } }];
